WITH scored AS (SELECT id, session_id, event_type, page, event_time, duration_sec, NTILE(5) OVER (PARTITION BY session_id ORDER BY duration_sec DESC, id ASC) AS duration_sec_bucket, LAG(duration_sec, 2, 0) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) AS prev_duration_sec, AVG(duration_sec) OVER (PARTITION BY page ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS duration_sec_avg_3, LAST_VALUE(page) IGNORE NULLS OVER (PARTITION BY page, session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_page, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS duration_sec_sum_30d FROM web_events) SELECT session_id, DATE_TRUNC('YEAR', event_time) AS year_start, MIN(event_time) AS first_seen, STDDEV_SAMP(duration_sec) AS duration_sec_stddev, MIN(duration_sec) AS min_duration_sec, ROUND(AVG(duration_sec_avg_3), 2) AS avg_duration_sec_avg_3, APPROX_PERCENTILE(duration_sec_bucket, 0.5) AS duration_sec_bucket_p50, COUNT(*) AS num_rows FROM scored GROUP BY session_id, DATE_TRUNC('YEAR', event_time) HAVING num_rows < 1;
